fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    // If the input array is empty or has only one element, return it unchanged
    if numbers.len() <= 1 {
        return numbers;
    }

    // Create a new vector to hold the result with the appropriate size
    let mut result = Vec::with_capacity(2 * numbers.len() - 1);

    // Iterate through the input array and insert elements and delimiters
    for (i, &num) in numbers.iter().enumerate() {
        result.push(num); // Push the current number
        if i < numbers.len() - 1 { // Avoid adding a delimiter after the last element
            result.push(delimiter); // Push the delimiter
        }
    }

    result // Return the constructed result
}